 {"id": "PEDS-C40-061", "sec": "Absence and JME basics", "page": 183, "q": "Hyperventilation is used clinically to precipitate/diagnose —", "opts": ["Infantile spasms", "Absence seizures", "JME", "Status epilepticus"], "ans": 1, "exp": "Absence seizures. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-062", "sec": "Absence and JME basics", "page": 183, "q": "A precipitant for absence seizures besides hyperventilation is —", "opts": ["High-protein meals", "Sleep only", "Stress", "Cold water"], "ans": 2, "exp": "Stress. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-063", "sec": "Absence and JME basics", "page": 183, "q": "Typical absence seizure EEG is —", "opts": ["4–6-Hz polyspike-and-wave", "1.5–2.5-Hz spike-and-wave", "10-Hz spike-and-wave", "3-Hz spike-and-wave"], "ans": 3, "exp": "3-Hz spike-and-wave. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-064", "sec": "Absence and JME basics", "page": 183, "q": "Atypical absence may be associated with GTCS/myoclonic seizures and —", "opts": ["10-Hz spike-and-wave", "PLEDS", "3-Hz spike-and-wave only", "Hypsarrhythmia"], "ans": 0, "exp": "10-Hz spike-and-wave. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-065", "sec": "Absence and JME basics", "page": 183, "q": "The drug of choice in India for absence seizure is —", "opts": ["Oxcarbazepine", "Valproate", "Ethosuximide", "Carbamazepine"], "ans": 1, "exp": "Valproate. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-066", "sec": "Absence and JME basics", "page": 183, "q": "The listed second-line absence drug is —", "opts": ["Clobazam", "Levetiracetam", "Lamotrigine", "Phenobarbitone"], "ans": 2, "exp": "Lamotrigine. (Book p183)", "type": "mcq"},
