 {"id": "PEDS-C40-068", "sec": "Absence and JME basics", "page": 183, "q": "Myoclonus is a sudden jerky movement caused by sudden —", "opts": ["Contraction of muscle groups", "Nerve demyelination", "Loss of all reflexes", "CSF pressure rise"], "ans": 0, "exp": "Contraction of muscle groups. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-069", "sec": "Absence and JME basics", "page": 183, "q": "Juvenile myoclonic epilepsy affects —", "opts": ["Older adults", "Adolescents", "Neonates", "Toddlers"], "ans": 1, "exp": "Adolescents. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-070", "sec": "Absence and JME basics", "page": 183, "q": "The inheritance of JME is —", "opts": ["Mitochondrial", "Autosomal dominant", "Polygenic", "X-linked recessive"], "ans": 2, "exp": "Polygenic. (Book p183)", "type": "mcq"},
 {"id": "PEDS-C40-071", "sec": "Absence and JME basics", "page": 183, "q": "Along with CLCN2, GABRA1 and CACNB4, the gene/protein listed as associated with juvenile myoclonic epilepsy is ___.", "opts": ["Myoclonin", "SCN1A", "KCNQ2", "MECP2"], "ans": 0, "exp": "JME-associated mutations include CLCN2, GABRA1, Myoclonin and CACNB4. (Book p183)", "type": "fill"},
 {"id": "PEDS-C40-072", "sec": "Absence and JME basics", "page": 183, "q": "The diagnosis is —", "opts": ["Typical absence seizure", "Focal epilepsy", "JME", "West syndrome"], "ans": 0, "exp": "Brief vacant stare/eye flutter with 3-Hz spike-wave in a schoolchild is typical absence seizure. (Book p183)", "type": "case", "stem": "A 12-year-old has repeated brief blank stares with eyelid flutter lasting 10 seconds, provoked by hyperventilation. EEG has 3-Hz spike-and-wave complexes."},
 {"id": "PEDS-C40-073", "sec": "Absence and JME basics", "page": 183, "q": "Odd one out (typical absence seizure features):", "opts": ["3-Hz spike-and-wave EEG", "4–6 Hz polyspike-wave EEG", "Vacant stare", "Eye flutter"], "ans": 1, "exp": "4–6-Hz polyspike-wave is the JME EEG pattern; the other three are typical absence features. (Book p183)", "type": "odd"},
 {"id": "PEDS-C40-074", "sec": "JME and West syndrome", "page": 184, "q": "Myoclonic episodes in JME typically occur on —", "opts": ["During fever only", "Deep sleep only", "Awakening", "After meals only"], "ans": 2, "exp": "Awakening. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-075", "sec": "JME and West syndrome", "page": 184, "q": "Inability to hold a toothbrush because of jerks on awakening is a clue to —", "opts": ["Lennox-Gastaut", "West syndrome", "Absence seizure", "JME"], "ans": 3, "exp": "JME. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-076", "sec": "JME and West syndrome", "page": 184, "q": "Consciousness during JME myoclonic episodes is —", "opts": ["Unaffected", "Associated with coma", "Always lost", "Absent for 30 minutes"], "ans": 0, "exp": "Unaffected. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-077", "sec": "JME and West syndrome", "page": 184, "q": "Other seizure patterns that may accompany JME are GTCS and —", "opts": ["Febrile seizures only", "Absence seizures", "Infantile spasms only", "Atonic seizures only"], "ans": 1, "exp": "Absence seizures. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-078", "sec": "JME and West syndrome", "page": 184, "q": "A precipitant for JME is —", "opts": ["Antibiotics", "Hyperventilation only", "Sleep deprivation", "Folate intake"], "ans": 2, "exp": "Sleep deprivation. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-079", "sec": "JME and West syndrome", "page": 184, "q": "Another listed JME precipitant is —", "opts": ["Urinary retention", "Cough", "Teething", "Alcohol intake"], "ans": 3, "exp": "Alcohol intake. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-080", "sec": "JME and West syndrome", "page": 184, "q": "The JME EEG pattern is —", "opts": ["4–6-Hz polyspike-and-wave", "PLEDS", "3-Hz spike-and-wave", "Hypsarrhythmia"], "ans": 0, "exp": "4–6-Hz polyspike-and-wave. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-081", "sec": "JME and West syndrome", "page": 184, "q": "The drug of choice for JME is —", "opts": ["Stiripentol", "Valproate", "Ethosuximide", "ACTH"], "ans": 1, "exp": "Valproate. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-082", "sec": "JME and West syndrome", "page": 184, "q": "JME treatment is lifelong because of increased risk of —", "opts": ["CKD", "CNS infection", "Adulthood seizures", "VUR"], "ans": 2, "exp": "Adulthood seizures. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-083", "sec": "JME and West syndrome", "page": 184, "q": "Epilepsy syndromes in this section are associated with brain injury, low IQ and —", "opts": ["Chronic diarrhea", "Cataract", "Renal stones", "Developmental abnormalities"], "ans": 3, "exp": "Developmental abnormalities. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-084", "sec": "JME and West syndrome", "page": 184, "q": "West syndrome has onset before ___ year of age.", "opts": ["1", "10", "2", "5"], "ans": 0, "exp": "1. (Book p184)", "type": "fill"},
 {"id": "PEDS-C40-085", "sec": "JME and West syndrome", "page": 184, "q": "Idiopathic West syndrome accounts for about —", "opts": ["90%", "30%", "70%", "10%"], "ans": 1, "exp": "30%. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-086", "sec": "JME and West syndrome", "page": 184, "q": "Symptomatic West syndrome accounts for about 70% and has the —", "opts": ["Normal EEG", "Best prognosis", "Worst outcome", "No CNS defect"], "ans": 2, "exp": "Worst outcome. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-087", "sec": "JME and West syndrome", "page": 184, "q": "Infantile spasms in West syndrome are also called —", "opts": ["Focal automatisms", "Absence stares", "Atonic drops", "Jack-knife seizures"], "ans": 3, "exp": "Jack-knife seizures. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-088", "sec": "JME and West syndrome", "page": 184, "q": "Salaam spells are repeated —", "opts": ["Neck flexion", "Eye blinking", "Neck extension", "Leg kicking"], "ans": 0, "exp": "Neck flexion. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-089", "sec": "JME and West syndrome", "page": 184, "q": "A component of West syndrome triad is —", "opts": ["Hypercalciuria", "Developmental regression", "Normal development", "Cranial bruit"], "ans": 1, "exp": "Developmental regression. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-090", "sec": "JME and West syndrome", "page": 184, "q": "Developmental regression means loss of —", "opts": ["CSF volume", "Only neonatal reflexes", "Previously acquired milestones", "Only muscle mass"], "ans": 2, "exp": "Previously acquired milestones. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-091", "sec": "JME and West syndrome", "page": 184, "q": "The West syndrome EEG is —", "opts": ["PLEDS", "4–6-Hz polyspike wave", "3-Hz spike-and-wave", "Hypsarrhythmia with high-voltage chaotic background"], "ans": 3, "exp": "Hypsarrhythmia with high-voltage chaotic background. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-092", "sec": "JME and West syndrome", "page": 184, "q": "West syndrome treatment should begin at the earliest because delay causes —", "opts": ["Irreversible brain damage", "Hearing recovery", "Renal failure", "Hypercalcemia"], "ans": 0, "exp": "Irreversible brain damage. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-093", "sec": "JME and West syndrome", "page": 184, "q": "The drug of choice for West syndrome is injectable —", "opts": ["Fosphenytoin", "ACTH", "Valproate", "Diazepam"], "ans": 1, "exp": "ACTH. (Book p184)", "type": "mcq"},
 {"id": "PEDS-C40-094", "sec": "JME and West syndrome", "page": 184, "q": "Vigabatrin is second line in West syndrome and is DOC with —", "opts": ["HUS", "Down syndrome", "Tuberous sclerosis", "VUR"], "ans": 2, "exp": "Tuberous sclerosis. (Book p184)", "type": "mcq"},
