 {"id": "PEDS-C40-111", "sec": "Epilepsy syndromes and status", "page": 185, "q": "Status epilepticus is an emergency characterized by —", "opts": ["No electrical activity", "One myoclonic jerk", "A brief 10-second stare", "Long-duration seizure"], "ans": 3, "exp": "Long-duration seizure. (Book p185)", "type": "mcq"},
 {"id": "PEDS-C40-112", "sec": "Epilepsy syndromes and status", "page": 185, "q": "In status epilepticus, T₁ (time to initiate treatment) is beyond ___ minutes.", "opts": ["5", "60", "15", "30"], "ans": 0, "exp": "5. (Book p185)", "type": "fill"},
