 {"id": "PEDS-C40-115", "sec": "Epilepsy syndromes and status", "page": 185, "q": "Status-epilepticus T₂ is the time after which ongoing seizure activity may cause long-term neuronal injury.", "opts": ["True", "False"], "ans": 0, "exp": "True — T₂ indicates prognosis and is >30 minutes in this chapter. (Book p185)", "type": "tf"},
 {"id": "PEDS-C40-116", "sec": "Epilepsy syndromes and status", "page": 185, "q": "The syndrome is —", "opts": ["Dravet syndrome", "JME", "West syndrome", "Lennox-Gastaut syndrome"], "ans": 0, "exp": "Severe myoclonic epilepsy of infancy with SCN1A is Dravet syndrome. (Book p185)", "type": "case", "stem": "An 8-month-old has difficult-to-control multiple seizure types. Genetic testing reveals SCN1A mutation affecting a sodium-channel alpha subunit."},
 {"id": "PEDS-C40-117", "sec": "Epilepsy syndromes and status", "page": 185, "q": "Odd one out (Lennox-Gastaut features):", "opts": ["1.5–2.5-Hz spike-wave", "Onset before one year with hypsarrhythmia", "Developmental delay", "Multiple refractory seizures"], "ans": 1, "exp": "Onset <1 year with hypsarrhythmia is West syndrome; the other features define Lennox-Gastaut. (Book p184–185)", "type": "odd"},
 {"id": "PEDS-C40-118", "sec": "Status epilepticus algorithm", "page": 186, "q": "The status treatment algorithm applies when seizure has lasted more than —", "opts": ["60 minutes", "30 seconds", "5 minutes", "15 minutes"], "ans": 2, "exp": "5 minutes. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-119", "sec": "Status epilepticus algorithm", "page": 186, "q": "The first stabilization sequence is airway, breathing, circulation and —", "opts": ["Defervescence", "Diet", "Diuresis", "Disability/neurologic status"], "ans": 3, "exp": "Disability/neurologic status. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-120", "sec": "Status epilepticus algorithm", "page": 186, "q": "During initial status stabilization, one should attempt —", "opts": ["IV access", "Immediate MRI", "Lumbar puncture first", "Renal biopsy"], "ans": 0, "exp": "IV access. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-121", "sec": "Status epilepticus algorithm", "page": 186, "q": "Blood glucose should be addressed before anti-epileptic escalation because hypoglycemia can cause —", "opts": ["Nephrosis", "Continued seizures", "Only rash", "Bradycardia only"], "ans": 1, "exp": "Continued seizures. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-122", "sec": "Status epilepticus algorithm", "page": 186, "q": "Hypoglycemia in the seizure algorithm is blood glucose below ___ mg/dL.", "opts": ["100", "40", "54", "70"], "ans": 2, "exp": "54. (Book p186)", "type": "fill"},
 {"id": "PEDS-C40-123", "sec": "Status epilepticus algorithm", "page": 186, "q": "Hypoglycemic seizures receive an immediate push of 10% dextrose —", "opts": ["50 mL/kg", "20 mL/kg", "0.5 mL/kg", "5 mL/kg"], "ans": 3, "exp": "5 mL/kg. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-124", "sec": "Status epilepticus algorithm", "page": 186, "q": "If hypoglycemia resolves after dextrose, next step is —", "opts": ["Monitoring", "VP shunt", "Fosphenytoin immediately", "Intubation in all"], "ans": 0, "exp": "Monitoring. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-125", "sec": "Status epilepticus algorithm", "page": 186, "q": "First-line antiseizure therapy after normal glucose is IV —", "opts": ["Levetiracetam", "Benzodiazepine", "Fosphenytoin", "Valproate"], "ans": 1, "exp": "Benzodiazepine. (Book p186)", "type": "mcq"},
