 {"id": "PEDS-C40-128", "sec": "Status epilepticus algorithm", "page": 186, "q": "Other listed second-line antiseizure options are valproate or —", "opts": ["Levetiracetam", "Clobazam", "Ethosuximide", "Stiripentol"], "ans": 0, "exp": "Levetiracetam. (Book p186)", "type": "mcq"},
 {"id": "PEDS-C40-129", "sec": "Status epilepticus algorithm", "page": 186, "q": "Refractory status is treated with anesthetic-dose continuous IV infusion of one of the following, EXCEPT —", "opts": ["Propofol", "Ceftriaxone", "Thiopental", "Midazolam"], "ans": 1, "exp": "Ceftriaxone. (Book p186)", "type": "mcq"},
